-- # Lernfeld 5: Cyberphysische Systeme > ## Datenbanken > - ER-Modelle

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann ein ER-Modell ohne Beziehungen zwischen Entitäten sinnvoll sein?', 2, '[{"text": "Nein", "correct": true, "because": "Beziehungen definieren die Struktur"}, {"text": "Ja", "correct": false, "because": "Ohne Beziehungen fehlt Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist jedes ER-Modell automatisch auf ein relationales Datenbanksystem übertragbar?', 2, '[{"text": "Ja", "correct": true, "because": "ER-Modelle sind für Relationen konzipiert"}, {"text": "Nein", "correct": false, "because": "Übertragung ist standardisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Können ER-Modelle auch Hierarchien zwischen Entitäten darstellen?', 2, '[{"text": "Ja", "correct": true, "because": "Spezialisierung und Generalisierung möglich"}, {"text": "Nein", "correct": false, "because": "Hierarchien sind umsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen alle Attribute in einem ER-Modell eindeutig sein?', 2, '[{"text": "Nein", "correct": true, "because": "Eindeutigkeit nur bei Schlüsseln nötig"}, {"text": "Ja", "correct": false, "because": "Normale Attribute können doppelt sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein ER-Modell unstrukturierte Daten direkt modellieren?', 2, '[{"text": "Nein", "correct": true, "because": "ER-Modelle sind für strukturierte Daten"}, {"text": "Ja", "correct": false, "because": "NoSQL besser für Unstrukturiertes"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Element eines ER-Modells repräsentiert eine reale Einheit?', 2, '[{"text": "Entität", "correct": true, "because": "Stellt Objekte dar"}, {"text": "Beziehung", "correct": false, "because": "Verknüpft Entitäten"}, {"text": "Attribut", "correct": false, "because": "Beschreibt Eigenschaften"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Art von Beziehung in einem ER-Modell beschreibt eine 1:n-Verknüpfung?', 3, '[{"text": "Eins-zu-viele", "correct": true, "because": "Eine Entität mit mehreren verknüpft"}, {"text": "Viele-zu-viele", "correct": false, "because": "n:m-Verknüpfung"}, {"text": "Eins-zu-eins", "correct": false, "because": "1:1-Verknüpfung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Symbol wird in ER-Diagrammen für eine Entität verwendet?', 2, '[{"text": "Rechteck", "correct": true, "because": "Standard für Entitäten"}, {"text": "Raute", "correct": false, "because": "Für Beziehungen"}, {"text": "Oval", "correct": false, "because": "Für Attribute"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Attribut in einem ER-Modell dient zur eindeutigen Identifikation?', 2, '[{"text": "Primärschlüssel", "correct": true, "because": "Einzigartig pro Entität"}, {"text": "Fremdschlüssel", "correct": false, "because": "Verknüpft Entitäten"}, {"text": "Normales Attribut", "correct": false, "because": "Nicht eindeutig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beziehung erfordert in einem ER-Modell eine zusätzliche Entität?', 2, '[{"text": "Viele-zu-viele", "correct": true, "because": "Benötigt Verbindungstabelle"}, {"text": "Eins-zu-eins", "correct": false, "because": "Direkt verknüpfbar"}, {"text": "Eins-zu-viele", "correct": false, "because": "Keine extra Entität nötig"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zu einem ER-Modell?', 4, '[{"text": "Entitäten", "correct": true, "because": "Repräsentieren Objekte"}, {"text": "Beziehungen", "correct": true, "because": "Verknüpfen Entitäten"}, {"text": "Attribute", "correct": true, "because": "Beschreiben Eigenschaften"}, {"text": "SQL-Abfragen", "correct": false, "because": "Implementierungsebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Beziehungen gibt es in ER-Modellen?', 3, '[{"text": "Eins-zu-eins", "correct": true, "because": "1:1-Verknüpfung"}, {"text": "Eins-zu-viele", "correct": true, "because": "1:n-Verknüpfung"}, {"text": "Viele-zu-eins", "correct": false, "because": "Variante von 1:n"}, {"text": "Viele-zu-viele", "correct": true, "because": "n:m-Verknüpfung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Attribute können in einem ER-Modell definiert werden?', 3, '[{"text": "Primärschlüssel", "correct": true, "because": "Eindeutige Identifikation"}, {"text": "Fremdschlüssel", "correct": true, "because": "Verknüpfung zu anderen Entitäten"}, {"text": "Code-Snippets", "correct": false, "because": "Nicht Teil des Modells"}, {"text": "Normale Attribute", "correct": true, "because": "Zusätzliche Eigenschaften"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein ER-Modell bei der Datenbankplanung?', 4, '[{"text": "Klarheit über Datenstruktur", "correct": true, "because": "Visualisiert Beziehungen"}, {"text": "Einfache Umsetzung in Relationen", "correct": true, "because": "Direkte Übertragung"}, {"text": "Automatische Datenbankgenerierung", "correct": false, "because": "Manuelle Umsetzung nötig"}, {"text": "Reduzierung von Redundanzen", "correct": true, "because": "Struktur optimiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei einem schlecht gestalteten ER-Modell auftreten?', 3, '[{"text": "Dateninkonsistenz", "correct": true, "because": "Fehlende Schlüssel"}, {"text": "Schwierige Wartung", "correct": true, "because": "Unklare Struktur"}, {"text": "Schnelle Abfragen", "correct": false, "because": "Eher langsamer"}, {"text": "Redundante Daten", "correct": true, "because": "Fehlende Normalisierung"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein ER-Modell kann ohne Primärschlüssel funktionieren. b) Beziehungen sind für die Datenstruktur essenziell.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Primärschlüssel nötig, Beziehungen zentral"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Viele-zu-viele-Beziehungen erfordern eine zusätzliche Entität. b) ER-Modelle sind nur für relationale Datenbanken geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "n:m braucht Tabelle, ER auch anderweitig nutzbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Attribute in einem ER-Modell müssen immer numerisch sein. b) Entitäten repräsentieren reale Objekte.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Attribute vielfältig, Entitäten real"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein ER-Modell kann Hierarchien modellieren. b) Fremdschlüssel sind im ER-Modell optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hierarchien möglich, Fremdschlüssel nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) ER-Modelle sind ungeeignet für NoSQL-Datenbanken. b) Primärschlüssel sichern die Eindeutigkeit von Entitäten.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "ER flexibel nutzbar, Primärschlüssel essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]');

